def flush(ids, tag):
    assert set(ids) <= set(P), tag
    for cid in ids:
        (OUT / f"{cid}.json").write_text(json.dumps(P[cid], ensure_ascii=False, indent=1), encoding="utf-8")
    print(tag, len(ids), "written")
flush(B11[:10], "B11-part1")

